function rnd(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function pick(arr)     { return arr[rnd(0, arr.length - 1)]; }

function fmtNum(n, dec = 1) { return parseFloat(n.toFixed(dec)); }

function buildCURP(name, yy, mm, dd, sex, state) {
  const parts = name.split(' ').filter(Boolean);
  const p1 = parts[0] ? parts[0].slice(0,1) : 'X';
  const vowel = parts[0] ? (parts[0].slice(1).match(/[AEIOU]/i) || ['X'])[0] : 'X';
  const p2 = parts[1] ? parts[1].slice(0,1) : 'X';
  const p3 = parts[2] ? parts[2].slice(0,1) : 'X';
  const s = sex === 'Masculino' ? 'H' : 'M';
  return `${p1}${vowel}${p2}${p3}${yy}${mm}${dd}${state}${s}N0${rnd(1,9)}`.toUpperCase();
}

function randomBirthdate(minAge, maxAge) {
  const now = new Date();
  const year = now.getFullYear() - rnd(minAge, maxAge);
  const month = String(rnd(1,12)).padStart(2,'0');
  const day   = String(rnd(1,28)).padStart(2,'0');
  return { str: `${year}-${month}-${day}`, yy: String(year).slice(2), mm: month, dd: day };
}

let _sampleId = 1;

function generateSampleStudents() {
  const students = [];
  GROUPS_LIST.forEach(group => {
    const count = rnd(5, 9);
    for (let i = 0; i < count; i++) {
      const isMale  = Math.random() > 0.48;
      const names   = isMale ? MALE_NAMES : FEMALE_NAMES;
      const nombre  = names[i % names.length];
      const gender  = isMale ? 'Masculino' : 'Femenino';
      const birth   = randomBirthdate(11, 15);
      const state   = pick(STATES);
      const tutorNombre = `${pick(TUTOR_FIRST)} ${pick(TUTOR_LAST)} ${pick(TUTOR_LAST)}`;
      const tutorBirth  = randomBirthdate(30, 55);
      const tutorGender = Math.random() > 0.4 ? 'Femenino' : 'Masculino';
      const beca    = Math.random() > 0.58 ? 'Sí' : 'No';
      const fn1     = tutorNombre.split(' ')[0].toLowerCase();
      const email   = `${fn1}${rnd(1,999)}@${pick(EMAIL_DOMS)}`;

      students.push({
        id:            _sampleId++,
        grado:         getGrade(group),
        grupo:         group,
        folio:         '',
        nombre,
        fechaNacimiento: birth.str,
        curpAlumno:    buildCURP(nombre, birth.yy, birth.mm, birth.dd, gender, state),
        genero:        gender,
        beca,
        peso:          fmtNum(rnd(320, 650) / 10),
        estatura:      rnd(130, 175),
        talla:         pick(TALLAS),
        tutor:         tutorNombre,
        telefono:      '55' + String(rnd(10000000, 99999999)),
        curpTutor:     buildCURP(tutorNombre, tutorBirth.yy, tutorBirth.mm, tutorBirth.dd, tutorGender, state),
        correo:        email,
        domicilio:     pick(STREETS) + ', Col. Centro',
        nivelEstudio:  pick(NIVEL_EST),
      });
    }
  });
  return students;
}

