async function upsertStudent(data, id = null) {
  const previousCache = allStudentsCache.map(student => ({ ...student }));

  // Generar grupoId para la cache
  let n = String(data.grado || '').charAt(0);
  let l = String(data.grupo || '').trim();
  data.grupoId = (l.length === 1 && n) ? (n + l) : l;

  // Optimistic update
  if (id) {
    const idx = allStudentsCache.findIndex(s => s.rowId === id || s.id === id);
    if (idx !== -1) {
      data.rowId = allStudentsCache[idx].rowId; // Enviar el rowId numérico real al backend
      allStudentsCache[idx] = { ...allStudentsCache[idx], ...data };
    }
  } else {
    data.id = Date.now().toString(); // Temp ID
    allStudentsCache.push(data);
  }
  
  // Re-render immediately
  refreshStudentViews();

  // Send to API
  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      body: JSON.stringify({ action: 'saveStudent', data: data }),
    });
    const result = await response.json();
    if (!result.success) {
      allStudentsCache = previousCache;
      refreshStudentViews();
      showToast('Error al guardar en la nube: ' + result.error, 'error');
      return false;
    }
    return true;
  } catch (error) {
    allStudentsCache = previousCache;
    refreshStudentViews();
    showToast('Error de conexión al guardar', 'error');
    return false;
  }
}

async function removeStudent(id) {
  const student = allStudentsCache.find(s => s.id === id || s.rowId === id);
  if (!student) return false;
  const previousCache = allStudentsCache.map(item => ({ ...item }));
  const realRowId = student.rowId;
  const sheetTab = student.grupoId; // "1A" instead of just "A"

  // Optimistic delete
  allStudentsCache = allStudentsCache.filter(s => s.id !== id && s.rowId !== id);
  
  refreshStudentViews();

  // Send to API
  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      body: JSON.stringify({ action: 'deleteStudent', grupo: sheetTab, id: realRowId }),
    });
    const result = await response.json();
    if (!result.success) {
      allStudentsCache = previousCache;
      refreshStudentViews();
      showToast('Error al eliminar en la nube: ' + result.error, 'error');
      return false;
    }
    return true;
  } catch (error) {
    allStudentsCache = previousCache;
    refreshStudentViews();
    showToast('Error de conexión al eliminar', 'error');
    return false;
  }
}

async function initData() {
  // Only fetch if not already loaded
  if (!isDataLoaded) {
    await fetchAllStudents();
  }
}

