const ATTENDANCE_STORAGE_KEY = 'ce_attendance_cache_v1';
const ATTENDANCE_STATUS_META = {
  present: { label: 'Asistió', short: '✓', className: 'attendance-present' },
  absent: { label: 'No asistió', short: 'X', className: 'attendance-absent' },
};

let attendanceCache = {};
let attendanceLoadedDate = null;
let attendanceLoadedMonth = null;
let attendanceApiReady = null;

try {
  attendanceCache = JSON.parse(localStorage.getItem(ATTENDANCE_STORAGE_KEY) || '{}') || {};
} catch (error) {
  attendanceCache = {};
}

function saveAttendanceCache() {
  try { localStorage.setItem(ATTENDANCE_STORAGE_KEY, JSON.stringify(attendanceCache)); }
  catch (error) { console.warn('No se pudo guardar la asistencia local:', error); }
}

function localDateString(date = new Date()) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function formatLongDate(dateString) {
  if (!dateString) return '';
  const date = new Date(`${dateString}T12:00:00`);
  return new Intl.DateTimeFormat('es-MX', {
    day: 'numeric', month: 'long', year: 'numeric'
  }).format(date);
}

function getAttendanceStudentId(student) {
  return String(student.id || `${student.grupoId || student.grupo}-${student.rowId || ''}`);
}

function getAttendanceKey(group, date, studentId) {
  return `${group}|${date}|${studentId}`;
}

function normalizeAttendanceStatus(status) {
  const value = String(status || '').trim().toLowerCase();
  if (['present', 'presente', 'asistio', 'asistió', '✓', '✔'].includes(value)) return 'present';
  if (['absent', 'falta', 'no asistio', 'no asistió', 'x', '✗', '✕'].includes(value)) return 'absent';
  return '';
}

function isAttendanceDateAllowed(date) {
  return Boolean(date) && date <= localDateString();
}

function setAttendanceDateLimits() {
  const today = localDateString();
  const dateInput = document.getElementById('attendance-date');
  const monthInput = document.getElementById('attendance-month');
  const directorMonthInput = document.getElementById('director-attendance-month');
  if (dateInput) {
    dateInput.max = today;
    if (dateInput.value && dateInput.value > today) dateInput.value = today;
  }
  if (monthInput) {
    monthInput.max = today.slice(0, 7);
    if (monthInput.value && monthInput.value > monthInput.max) monthInput.value = monthInput.max;
  }
  if (directorMonthInput) {
    directorMonthInput.max = today.slice(0, 7);
    if (directorMonthInput.value && directorMonthInput.value > directorMonthInput.max) directorMonthInput.value = directorMonthInput.max;
  }
}

async function ensureAttendanceApiReady() {
  if (attendanceApiReady !== null) return attendanceApiReady;
  try {
    const response = await fetch(API_URL, {
      method: 'POST',
      body: JSON.stringify({ action: 'getAttendanceConfig' }),
    });
    const result = await response.json();
    attendanceApiReady = Boolean(result.success && result.mode === 'formatted-monthly-sheet');
  } catch (error) {
    attendanceApiReady = false;
  }
  return attendanceApiReady;
}

function attendanceApiSetupMessage() {
  return '<i class="fa-solid fa-triangle-exclamation"></i> Falta publicar la versión del Apps Script que usa las hojas ASISTENCIA (GRUPO). No se escribió ninguna hoja.';
}

function getAttendanceRecord(group, date, studentId) {
  const record = attendanceCache[getAttendanceKey(group, date, studentId)] || {
    date,
    group,
    studentId,
    status: '',
    note: '',
    synced: true,
  };
  return { ...record, status: normalizeAttendanceStatus(record.status) };
}

function reconcileAttendanceCacheDate(group, date, serverRecords) {
  const serverKeys = new Set((serverRecords || [])
    .map(record => String(record.studentId || '').trim())
    .filter(Boolean)
    .map(studentId => getAttendanceKey(group, date, studentId)));

  Object.entries(attendanceCache).forEach(([key, record]) => {
    if (record.group !== group || record.date !== date || record.synced === false) return;
    if (!serverKeys.has(key)) delete attendanceCache[key];
  });
}

function setAttendanceRecord(group, date, studentId, values) {
  const key = getAttendanceKey(group, date, studentId);
  attendanceCache[key] = {
    ...getAttendanceRecord(group, date, studentId),
    ...values,
    date,
    group,
    studentId,
    synced: false,
    updatedAt: new Date().toISOString(),
  };
  saveAttendanceCache();
}

function renderAttendanceStatusButtons(studentId, selectedStatus) {
  return Object.entries(ATTENDANCE_STATUS_META).map(([status, meta]) => `
    <button type="button" class="attendance-status-btn ${meta.className} ${selectedStatus === status ? 'selected' : ''}"
      onclick='setAttendanceStatus(${JSON.stringify(studentId)}, ${JSON.stringify(status)})'
      aria-pressed="${selectedStatus === status}" title="${meta.label}">
      <span class="attendance-status-short">${meta.short}</span>
      <span class="attendance-status-label">${meta.label}</span>
    </button>
  `).join('');
}

function updateAttendanceSummary(students, date) {
  const records = students.map(student =>
    getAttendanceRecord(currentUser.group, date, getAttendanceStudentId(student))
  );
  const count = status => records.filter(record => record.status === status).length;
  const pending = records.filter(record => !record.status).length;
  const summary = document.getElementById('attendance-summary');
  if (!summary) return;
  summary.innerHTML = `
    <span class="attendance-summary-item summary-total"><strong>${students.length}</strong> alumnos</span>
    <span class="attendance-summary-item summary-pending"><strong>${pending}</strong> pendientes</span>
    <span class="attendance-summary-item summary-present"><strong>${count('present')}</strong> asistieron</span>
    <span class="attendance-summary-item summary-absent"><strong>${count('absent')}</strong> no asistieron</span>
  `;
}

function renderAttendanceTable() {
  if (!currentUser || currentUser.role !== 'teacher') return;
  setAttendanceDateLimits();
  const date = document.getElementById('attendance-date')?.value || localDateString();
  const students = getStudentsByGroup(currentUser.group);
  const tbody = document.getElementById('attendance-tbody');
  const table = document.getElementById('attendance-table');
  const empty = document.getElementById('attendance-empty');
  if (!tbody || !table || !empty) return;

  updateAttendanceSummary(students, date);
  if (!students.length) {
    table.style.display = 'none';
    empty.classList.remove('hidden');
    return;
  }

  table.style.display = '';
  empty.classList.add('hidden');
  tbody.innerHTML = students.map((student, index) => {
    const studentId = getAttendanceStudentId(student);
    const record = getAttendanceRecord(currentUser.group, date, studentId);
    return `
      <tr>
        <td class="td-number">${index + 1}</td>
        <td class="td-name">${escHtml(student.nombre) || 'Alumno sin nombre'}</td>
        <td>
          <div class="attendance-status-group" role="group" aria-label="Estado de ${escHtml(student.nombre) || 'alumno'}">
            ${renderAttendanceStatusButtons(studentId, record.status)}
          </div>
        </td>
      </tr>
    `;
  }).join('');
  updateAttendanceSyncStatus();
}

function localMonthString(date = new Date()) {
  return localDateString(date).slice(0, 7);
}

function getAttendanceWorkdays(month) {
  const [year, monthNumber] = String(month || '').split('-').map(Number);
  if (!year || !monthNumber) return [];
  const daysInMonth = new Date(year, monthNumber, 0).getDate();
  const weekdays = ['D', 'L', 'M', 'X', 'J', 'V', 'S'];
  const days = [];
  for (let day = 1; day <= daysInMonth; day++) {
    const date = new Date(year, monthNumber - 1, day, 12);
    const weekday = date.getDay();
    if (weekday === 0 || weekday === 6) continue;
    days.push({
      date: localDateString(date),
      number: day,
      weekday: weekdays[weekday],
    });
  }
  return days;
}

function formatMonthLabel(month) {
  if (!month) return '';
  const date = new Date(`${month}-01T12:00:00`);
  return new Intl.DateTimeFormat('es-MX', { month: 'long', year: 'numeric' }).format(date);
}

function updateAttendanceMonthSummary(students, days, month) {
  const visibleDays = days.filter(day => day.date <= localDateString());
  const records = students.flatMap(student => visibleDays.map(day => ({
    student,
    day,
    record: getAttendanceRecord(currentUser.group, day.date, getAttendanceStudentId(student)),
  })));
  const count = status => records.filter(item => item.record.status === status).length;
  const pending = records.filter(item => !item.record.status).length;
  const summary = document.getElementById('attendance-month-summary');
  if (!summary) return;
  summary.innerHTML = `
    <span class="attendance-summary-item summary-total"><strong>${students.length}</strong> alumnos</span>
    <span class="attendance-summary-item"><strong>${days.length}</strong> días hábiles</span>
    <span class="attendance-summary-item summary-pending"><strong>${pending}</strong> pendientes</span>
    <span class="attendance-summary-item summary-present"><strong>${count('present')}</strong> asistieron</span>
    <span class="attendance-summary-item summary-absent"><strong>${count('absent')}</strong> no asistieron</span>
  `;
}

function updateAttendanceMonthSyncStatus(message = '') {
  const statusEl = document.getElementById('attendance-month-sync-status');
  if (!statusEl) return;
  const month = document.getElementById('attendance-month')?.value;
  const group = currentUser?.group;
  if (!month || !group) {
    statusEl.textContent = '';
    return;
  }
  const pending = Object.values(attendanceCache).filter(record =>
    record.group === group && String(record.date || '').startsWith(`${month}-`) && record.synced === false
  ).length;
  statusEl.className = `attendance-sync-status ${pending ? 'is-pending' : 'is-synced'}`;
  statusEl.innerHTML = message || (pending
    ? `<i class="fa-solid fa-mobile-screen-button"></i> ${pending} registro(s) local(es) pendiente(s) de sincronizar.`
    : `<i class="fa-solid fa-cloud-check"></i> Historial consultado: ${escHtml(formatMonthLabel(month))}.`);
}

function renderAttendanceMonthTable() {
  if (!currentUser || currentUser.role !== 'teacher') return;
  setAttendanceDateLimits();
  const month = document.getElementById('attendance-month')?.value || localMonthString();
  const students = getStudentsByGroup(currentUser.group);
  const days = getAttendanceWorkdays(month);
  const table = document.getElementById('attendance-month-table');
  const head = document.getElementById('attendance-month-head');
  const tbody = document.getElementById('attendance-month-tbody');
  const empty = document.getElementById('attendance-month-empty');
  if (!table || !head || !tbody || !empty) return;

  updateAttendanceMonthSummary(students, days, month);
  if (!students.length) {
    table.style.display = 'none';
    empty.classList.remove('hidden');
    updateAttendanceMonthSyncStatus();
    return;
  }

  table.style.display = '';
  empty.classList.add('hidden');
  head.innerHTML = `
    <tr>
      <th>#</th>
      <th>Nombre del Alumno</th>
      ${days.map(day => `<th class="attendance-month-day-head"><span>${day.weekday}</span><small>${day.number}</small></th>`).join('')}
    </tr>
  `;
  const today = localDateString();
  tbody.innerHTML = students.map((student, index) => {
    const studentId = getAttendanceStudentId(student);
    return `
      <tr>
        <td class="td-number">${index + 1}</td>
        <td class="td-name attendance-month-name">${escHtml(student.nombre) || 'Alumno sin nombre'}</td>
        ${days.map(day => {
          const record = getAttendanceRecord(currentUser.group, day.date, studentId);
          const status = ATTENDANCE_STATUS_META[record.status];
          const label = status ? status.label : 'Pendiente';
          const note = record.note ? ` · ${record.note}` : '';
          const isFuture = day.date > today;
          const cell = isFuture
            ? `<span class="attendance-month-cell attendance-month-empty-cell attendance-month-future-cell" title="Aún no disponible">—</span>`
            : `<button type="button" class="attendance-month-cell ${status ? status.className : 'attendance-month-empty-cell'}"
                onclick='openAttendanceDayModal(${JSON.stringify(currentUser.group)}, ${JSON.stringify(day.date)})'
                title="${escHtml(`${formatLongDate(day.date)}: ${label}${note}`)}"
                aria-label="${escHtml(`${student.nombre || 'Alumno'} · ${formatLongDate(day.date)} · ${label}`)}">
                ${status ? status.short : '—'}
              </button>`;
          return `<td class="attendance-month-cell-wrap">${cell}</td>`;
        }).join('')}
      </tr>
    `;
  }).join('');
  updateAttendanceMonthSyncStatus();
}

function setAttendanceCurrentMonth() {
  const monthInput = document.getElementById('attendance-month');
  if (!monthInput) return;
  monthInput.value = localMonthString();
  changeAttendanceMonth();
}

function changeAttendanceMonth() {
  setAttendanceDateLimits();
  const monthInput = document.getElementById('attendance-month');
  if (monthInput && monthInput.value > localMonthString()) {
    monthInput.value = localMonthString();
    showToast('No se pueden consultar meses futuros', 'info');
  }
  attendanceLoadedMonth = null;
  renderAttendanceMonthTable();
  fetchAttendanceMonth();
}

async function requestAttendanceMonthBatch(group, month) {
  const response = await fetch(API_URL, {
    method: 'POST',
    body: JSON.stringify({ action: 'getAttendanceMonth', group, month }),
  });
  const result = await response.json();
  if (!result.success && result.error === 'Acción no válida') return null;
  if (!result.success) throw new Error(result.error || 'No se pudo consultar el historial');
  if (result.mode !== 'formatted-monthly-sheet' || result.sheetName !== `ASISTENCIA (${group})`) {
    throw new Error('La API no está conectada a la hoja mensual del grupo');
  }
  return result;
}

function mergeAttendanceMonthServerRecords(group, responses) {
  const today = localDateString();
  (responses || []).forEach(({ date, records }) => {
    if (!date || date > today) return;
    const serverRecords = Array.isArray(records) ? records : [];
    reconcileAttendanceCacheDate(group, date, serverRecords);
    serverRecords.forEach(serverRecord => {
      const studentId = String(serverRecord.studentId || '').trim();
      if (!studentId) return;
      const key = getAttendanceKey(group, date, studentId);
      if (!attendanceCache[key] || attendanceCache[key].synced !== false) {
        attendanceCache[key] = {
          ...serverRecord,
          studentId,
          group,
          date,
          status: normalizeAttendanceStatus(serverRecord.status),
          synced: true,
        };
      }
    });
  });
  saveAttendanceCache();
}

async function fetchAttendanceMonth() {
  if (!currentUser || currentUser.role !== 'teacher') return;
  const month = document.getElementById('attendance-month')?.value;
  if (!month) return;
  const group = currentUser.group;
  attendanceLoadedMonth = `${group}|${month}`;
  updateAttendanceMonthSyncStatus('<i class="fa-solid fa-spinner fa-spin"></i> Consultando el historial mensual...');

  if (navigator.onLine === false) {
    renderAttendanceMonthTable();
    updateAttendanceMonthSyncStatus();
    return;
  }

  try {
    const result = await requestAttendanceMonthBatch(group, month);
    if (result === null) return fetchAttendanceMonthLegacy();
    mergeAttendanceMonthServerRecords(group, result.data);
    renderAttendanceMonthTable();
    updateAttendanceMonthSyncStatus('<i class="fa-solid fa-cloud-check"></i> Historial mensual sincronizado.');
  } catch (error) {
    renderAttendanceMonthTable();
    updateAttendanceMonthSyncStatus('<i class="fa-solid fa-mobile-screen-button"></i> Modo local: se muestran las capturas disponibles en este dispositivo.');
  }
}

async function fetchAttendanceMonthLegacy() {
  if (!currentUser || currentUser.role !== 'teacher') return;
  const month = document.getElementById('attendance-month')?.value;
  if (!month) return;
  const group = currentUser.group;
  const days = getAttendanceWorkdays(month);
  const daysToFetch = days.filter(day => day.date <= localDateString());
  attendanceLoadedMonth = `${group}|${month}`;
  updateAttendanceMonthSyncStatus('<i class="fa-solid fa-spinner fa-spin"></i> Consultando el historial mensual...');

  if (navigator.onLine === false) {
    renderAttendanceMonthTable();
    updateAttendanceMonthSyncStatus();
    return;
  }

  if (!(await ensureAttendanceApiReady())) {
    renderAttendanceMonthTable();
    updateAttendanceMonthSyncStatus(attendanceApiSetupMessage());
    return;
  }

  try {
    const responses = [];
    for (let index = 0; index < daysToFetch.length; index += 4) {
      const batch = daysToFetch.slice(index, index + 4);
      const batchResponses = await Promise.all(batch.map(async day => {
        const response = await fetch(API_URL, {
          method: 'POST',
          body: JSON.stringify({ action: 'getAttendance', group, date: day.date }),
        });
        const result = await response.json();
        if (!result.success) throw new Error(result.error || 'No se pudo consultar el historial');
        if (result.sheetName !== `ASISTENCIA (${group})`) throw new Error('La API no está conectada a la hoja mensual del grupo');
        return { date: day.date, records: result.data || [] };
      }));
      responses.push(...batchResponses);
    }

    responses.forEach(({ date, records }) => {
      reconcileAttendanceCacheDate(group, date, records);
      records.forEach(serverRecord => {
        const studentId = String(serverRecord.studentId || '');
        if (!studentId) return;
        const key = getAttendanceKey(group, date, studentId);
        if (!attendanceCache[key] || attendanceCache[key].synced !== false) {
          attendanceCache[key] = {
            ...serverRecord,
            studentId,
            group,
            date,
            status: normalizeAttendanceStatus(serverRecord.status),
            synced: true,
          };
        }
      });
    });
    saveAttendanceCache();
    renderAttendanceMonthTable();
    updateAttendanceMonthSyncStatus('<i class="fa-solid fa-cloud-check"></i> Historial mensual sincronizado.');
  } catch (error) {
    renderAttendanceMonthTable();
    updateAttendanceMonthSyncStatus('<i class="fa-solid fa-mobile-screen-button"></i> Modo local: se muestran las capturas disponibles en este dispositivo.');
  }
}

function closeAttendanceDayModal(event) {
  const overlay = document.getElementById('attendance-day-modal');
  if (!overlay) return;
  if (event && event.target !== overlay) return;
  overlay.classList.add('hidden');
  document.body.style.overflow = '';
}

function openAttendanceDayModal(group, date) {
  if (!currentUser || !group || !isAttendanceDateAllowed(date)) return;
  if (currentUser.role === 'teacher' && currentUser.group !== group) return;

  const students = getStudentsByGroup(group);
  const records = students.map(student => ({
    student,
    record: getAttendanceRecord(group, date, getAttendanceStudentId(student)),
  }));
  const present = records.filter(item => item.record.status === 'present').length;
  const absent = records.filter(item => item.record.status === 'absent').length;
  const pending = records.length - present - absent;

  const title = document.getElementById('attendance-day-modal-title');
  const subtitle = document.getElementById('attendance-day-modal-subtitle');
  const summary = document.getElementById('attendance-day-modal-summary');
  const tbody = document.getElementById('attendance-day-modal-tbody');
  const mode = document.getElementById('attendance-day-modal-mode');
  const editButton = document.getElementById('attendance-day-modal-edit-btn');
  const overlay = document.getElementById('attendance-day-modal');
  if (!title || !subtitle || !summary || !tbody || !mode || !editButton || !overlay) return;

  title.textContent = 'Detalle de asistencia';
  subtitle.textContent = `Grupo ${group} · ${formatLongDate(date)}`;
  summary.innerHTML = `
    <span class="attendance-summary-item summary-total"><strong>${students.length}</strong> alumnos</span>
    <span class="attendance-summary-item summary-present"><strong>${present}</strong> asistieron</span>
    <span class="attendance-summary-item summary-absent"><strong>${absent}</strong> no asistieron</span>
    <span class="attendance-summary-item summary-pending"><strong>${pending}</strong> pendientes</span>
  `;
  tbody.innerHTML = records.map(({ student, record }, index) => {
    const status = ATTENDANCE_STATUS_META[record.status];
    const statusLabel = status ? `${status.short} ${status.label}` : '— Pendiente';
    return `
      <tr>
        <td class="td-number">${index + 1}</td>
        <td class="td-name">${escHtml(student.nombre) || 'Alumno sin nombre'}</td>
        <td class="attendance-modal-status ${status ? status.className : ''}">${escHtml(statusLabel)}</td>
        <td>${escHtml(record.note) || '—'}</td>
      </tr>
    `;
  }).join('');

  const canEdit = currentUser.role === 'teacher' && currentUser.group === group;
  mode.textContent = canEdit
    ? 'El maestro puede corregir este día desde la captura diaria.'
    : 'Vista de solo lectura para dirección.';
  editButton.classList.toggle('hidden', !canEdit);
  editButton.onclick = canEdit ? () => {
    closeAttendanceDayModal();
    openAttendanceDateFromMonth(date);
  } : null;

  overlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function openAttendanceDateFromMonth(date) {
  const dateInput = document.getElementById('attendance-date');
  if (!dateInput) return;
  if (!isAttendanceDateAllowed(date)) return;
  dateInput.value = date;
  attendanceLoadedDate = null;
  switchTeacherTab('attendance');
}

