// =====================================================
// TOAST
// =====================================================

let toastTimer = null;

function showToast(msg, type = 'success') {
  const toast  = document.getElementById('toast');
  const icon   = document.getElementById('toast-icon');
  const msgEl  = document.getElementById('toast-msg');
  const icons  = { success:'fa-check-circle', error:'fa-trash-can', info:'fa-circle-info' };

  toast.className  = `toast toast-${type}`;
  icon.className   = `fa-solid ${icons[type] || 'fa-check-circle'}`;
  msgEl.textContent = msg;

  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.add('hidden'), 3200);
}

// =====================================================
// UTILITIES
// =====================================================

function fmtDate(str) {
  if (!str) return '—';
  const [y, m, d] = str.split('-');
  return `${d}/${m}/${y}`;
}

function fmtNum(n, dec = 1) {
  return parseFloat(parseFloat(n).toFixed(dec));
}

function escHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g,'&amp;').replace(/</g,'&lt;')
    .replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// =====================================================
// KEYBOARD SHORTCUTS
// =====================================================

document.addEventListener('keydown', e => {
  // Enter on login
  if (e.key === 'Enter' && document.getElementById('view-login').classList.contains('active')) {
    login();
  }
  // Escape closes drawer and confirm dialog
  if (e.key === 'Escape') {
    closeAttendanceDayModal();
    closeStudentDrawer();
    closeStaffDrawer();
    closeConfirm();
  }
});

// CURP input: force uppercase
document.addEventListener('input', e => {
  if (e.target.classList.contains('uppercase')) {
    const pos = e.target.selectionStart;
    e.target.value = e.target.value.toUpperCase();
    e.target.setSelectionRange(pos, pos);
  }
});

